<?php
declare(strict_types=1);
use Karoor\Core\Helpers;
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false||$id===null){http_response_code(404);exit('Invoice not found.');}$companyId=(int)$currentUser['company_id'];$scope=$auth->can('sales.view')?'':' AND s.salesperson_id=:user';$params=['id'=>$id,'company'=>$companyId];if($scope!=='')$params['user']=(int)$currentUser['id'];$sale=$database->fetchOne('SELECT s.*,c.name customer_name,c.customer_code,c.phone customer_phone,c.email customer_email,c.address customer_address,w.name warehouse_name,u.full_name salesperson_name,co.name company_name,co.legal_name,co.phone company_phone,co.email company_email,co.website,co.address_line1,co.address_line2,co.city,co.region,co.tax_number,co.vat_number,co.currency_code,co.logo_path FROM sales s LEFT JOIN customers c ON c.id=s.customer_id INNER JOIN warehouses w ON w.id=s.warehouse_id INNER JOIN users u ON u.id=s.salesperson_id INNER JOIN companies co ON co.id=s.company_id WHERE s.id=:id AND s.company_id=:company AND s.deleted_at IS NULL'.$scope,$params);if($sale===null){http_response_code(404);exit('Invoice not found.');}$items=$database->fetchAll('SELECT product_name,sku,quantity,unit_price,discount_amount,tax_rate,tax_amount,line_total FROM sale_items WHERE sale_id=:id ORDER BY id',['id'=>$id]);$payments=$database->fetchAll('SELECT p.payment_number,p.payment_method,p.payment_date,p.amount,p.reference_number FROM sale_payments sp INNER JOIN payments p ON p.id=sp.payment_id WHERE sp.sale_id=:id AND p.deleted_at IS NULL ORDER BY p.payment_date',['id'=>$id]);
