<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice <?= Helpers::escape($sale['invoice_number']) ?></title><link rel="stylesheet" href="<?= Helpers::escape(Helpers::appPath($config,'/assets/css/print.css')) ?>"></head><body class="print-document invoice-document"><div class="print-toolbar"><button type="button" data-print-trigger>Print invoice</button><a href="<?= Helpers::escape(Helpers::appPath($config,'/sales')) ?>">Back to sales</a></div><main class="invoice"><header class="invoice-header"><div class="print-brand"><?php if($sale['logo_path']):?><img src="<?= Helpers::escape(Helpers::appPath($config,'/'.$sale['logo_path'])) ?>" alt=""><?php endif;?><h1><?= Helpers::escape($sale['company_name']) ?></h1><p><?= Helpers::escape(implode(', ',array_filter([$sale['address_line1'],$sale['address_line2'],$sale['city'],$sale['region']]))) ?><br><?= Helpers::escape($sale['company_phone']) ?> · <?= Helpers::escape($sale['company_email']) ?></p></div><div><span class="document-label">INVOICE</span><h2><?= Helpers::escape($sale['invoice_number']) ?></h2><p><?= Helpers::escape(date('F j, Y',strtotime($sale['sale_date']))) ?><br><span class="status"><?= Helpers::escape($sale['status']) ?></span></p></div></header><section class="invoice-parties"><div><small>BILL TO</small><strong><?= Helpers::escape($sale['customer_name']??'Walk-in customer') ?></strong><span><?= Helpers::escape($sale['customer_address']??'') ?></span><span><?= Helpers::escape($sale['customer_phone']??'') ?></span></div><div><small>DETAILS</small><span>Warehouse: <?= Helpers::escape($sale['warehouse_name']) ?></span><span>Salesperson: <?= Helpers::escape($sale['salesperson_name']) ?></span><?php if($sale['tax_number']):?><span>TIN: <?= Helpers::escape($sale['tax_number']) ?></span><?php endif;?><?php if($sale['vat_number']):?><span>VAT: <?= Helpers::escape($sale['vat_number']) ?></span><?php endif;?></div></section><table><thead><tr><th>Item</th><th>SKU</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Discount</th><th class="num">Tax</th><th class="num">Total</th></tr></thead><tbody><?php foreach($items as$item):?><tr><td><?= Helpers::escape($item['product_name']) ?></td><td><?= Helpers::escape($item['sku']) ?></td><td class="num"><?= number_format((float)$item['quantity'],2) ?></td><td class="num"><?= number_format((float)$item['unit_price'],2) ?></td><td class="num"><?= number_format((float)$item['discount_amount'],2) ?></td><td class="num"><?= number_format((float)$item['tax_amount'],2) ?></td><td class="num"><?= number_format((float)$item['line_total'],2) ?></td></tr><?php endforeach;?></tbody></table><div class="invoice-summary"><div><?php if($payments):?><h3>Payment history</h3><?php foreach($payments as$payment):?><p><?= Helpers::escape($payment['payment_number'].' · '.$payment['payment_method']) ?> <strong><?= number_format((float)$payment['amount'],2) ?></strong></p><?php endforeach;?><?php endif;?></div><dl class="totals"><dt>Subtotal</dt><dd><?= number_format((float)$sale['subtotal'],2) ?></dd><dt>Discount</dt><dd><?= number_format((float)$sale['discount_amount'],2) ?></dd><dt>Tax</dt><dd><?= number_format((float)$sale['tax_amount'],2) ?></dd><dt class="grand">Total <?= Helpers::escape($sale['currency_code']) ?></dt><dd class="grand"><?= number_format((float)$sale['total_amount'],2) ?></dd><dt>Paid</dt><dd><?= number_format((float)$sale['paid_amount'],2) ?></dd><dt>Balance due</dt><dd><?= number_format((float)$sale['due_amount'],2) ?></dd></dl></div><?php if($sale['notes']):?><section class="notes"><h3>Notes</h3><p><?= nl2br(Helpers::escape($sale['notes'])) ?></p></section><?php endif;?><footer>Generated securely by Karoor ERP</footer></main><script src="<?= Helpers::escape(Helpers::appPath($config,'/assets/js/print.js')) ?>" defer></script></body></html>
